-- ===========================================================================
-- Hand-written below: what Prisma cannot express.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One active booking per table per date, for every channel (plan §4.5, §7.5,
-- D21).
--
-- The website, the app and Reception all run one command, and this index
-- decides any race between them: two bookings for one table and date cannot
-- both commit, whatever the service checked first. Cancelled, completed and
-- no-show bookings leave the index, so the table can be booked again.
--
-- Named as Prisma names a unique index (`<Model>_<field>_<field>_key`), so
-- `uniqueViolationTargets` reads a clash as ["tableId", "businessDate"] and
-- the service can answer 409 with the booking sentence.
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX "Reservation_tableId_businessDate_key"
  ON "Reservation" ("tableId", "businessDate")
  WHERE "status" IN ('CONFIRMED', 'CHECKED_IN');

-- One open allocation per table (plan §4.5): a table is either free or held
-- by exactly one Occupied or Locked session. Ended sessions are history and
-- leave the index. Read as ["tableId"] on a clash.
CREATE UNIQUE INDEX "TableSession_tableId_key"
  ON "TableSession" ("tableId")
  WHERE "endedAt" IS NULL;

-- ---------------------------------------------------------------------------
-- Bills, lines, dockets and payments: the ranges the staff app enforces, as
-- a backstop for a write that does not come through a route.
-- ---------------------------------------------------------------------------
ALTER TABLE "Order"
  ADD CONSTRAINT "Order_values_check" CHECK (
    "revision" >= 0
    AND "vatBps" >= 0
    AND "serviceBps" >= 0
    AND "discountKobo" >= 0
    AND "depositKobo" >= 0
  );

-- A settled bill records when; a reversal returns it to Payment and clears
-- the time, so no other state carries one.
ALTER TABLE "Order"
  ADD CONSTRAINT "Order_settled_check"
  CHECK (("status" = 'SETTLED') = ("settledAt" IS NOT NULL));

-- "Maximum item quantity is 999."; a line at zero is removed, never stored.
ALTER TABLE "OrderLine"
  ADD CONSTRAINT "OrderLine_values_check"
  CHECK ("qty" BETWEEN 1 AND 999 AND "unitPriceKobo" >= 0);

ALTER TABLE "Docket"
  ADD CONSTRAINT "Docket_revision_check" CHECK ("revision" >= 1);

-- A payment of nothing records nothing; a refund is negative. A reversed
-- payment says when, and only a reversed one does. The card is its last four
-- digits, never more (plan §8.5).
ALTER TABLE "Payment"
  ADD CONSTRAINT "Payment_amount_check" CHECK ("amountKobo" <> 0);

ALTER TABLE "Payment"
  ADD CONSTRAINT "Payment_reversed_check"
  CHECK ("reversed" = ("reversedAt" IS NOT NULL));

ALTER TABLE "Payment"
  ADD CONSTRAINT "Payment_card_last4_check"
  CHECK ("cardLast4" IS NULL OR "cardLast4" ~ '^[0-9]{4}$');

-- The difference is always counted − expected, and a count is never below
-- zero ("Enter a valid cash count.").
ALTER TABLE "CashCount"
  ADD CONSTRAINT "CashCount_values_check" CHECK (
    "countedKobo" >= 0
    AND "differenceKobo" = "countedKobo" - "expectedKobo"
  );

ALTER TABLE "KitchenEntry"
  ADD CONSTRAINT "KitchenEntry_revision_check" CHECK ("revision" >= 1);

-- ---------------------------------------------------------------------------
-- Reservations and table sessions.
-- ---------------------------------------------------------------------------

-- An arrival time within the day, a party of at least one, and deposit
-- credit that is never more than the deposit (D38). A cancelled booking
-- records when, and only a cancelled one does.
ALTER TABLE "Reservation"
  ADD CONSTRAINT "Reservation_values_check" CHECK (
    "startMinutes" BETWEEN 0 AND 1439
    AND "party" > 0
    AND "depositKobo" >= 0
    AND "depositUsedKobo" BETWEEN 0 AND "depositKobo"
  );

ALTER TABLE "Reservation"
  ADD CONSTRAINT "Reservation_cancelled_check"
  CHECK (("status" = 'CANCELLED') = ("cancelledAt" IS NOT NULL));

-- Occupied: a guest and a party ("Enter a guest name and a party size within
-- capacity."). Locked: a reason ("Enter a reason for locking this
-- position."). An ended session says who ended it, and only an ended one
-- does; the closer may be null afterwards only if that staff row were ever
-- removed (it is not: staff are deactivated).
ALTER TABLE "TableSession"
  ADD CONSTRAINT "TableSession_shape_check" CHECK (
    ("status" = 'OCCUPIED' AND "guest" <> '' AND "party" > 0)
    OR ("status" = 'LOCKED' AND "note" <> '' AND "party" >= 0)
  );

ALTER TABLE "TableSession"
  ADD CONSTRAINT "TableSession_closed_check"
  CHECK ("endedAt" IS NOT NULL OR "closedById" IS NULL);

-- ---------------------------------------------------------------------------
-- Stock.
-- ---------------------------------------------------------------------------

-- A movement moves something: a zero would be a row that explains no change
-- (the staff app writes none).
ALTER TABLE "StockMovement"
  ADD CONSTRAINT "StockMovement_qty_check" CHECK ("qty" <> 0);

-- "Quantities must be whole numbers above zero."
ALTER TABLE "KitchenMapping"
  ADD CONSTRAINT "KitchenMapping_qty_check" CHECK ("qty" > 0);

-- Stock movements are append-only (plan §4.6), as the audit log and the
-- approvals ledger are: the movements are the truth and the balance is their
-- running sum, so a movement edited or deleted would leave a balance no
-- history explains. A correction is a new movement. A row trigger refuses
-- UPDATE and DELETE, and a statement trigger refuses TRUNCATE, which bypasses
-- row triggers. The table's owner can still drop the trigger; that is a
-- reviewed migration, not an accident.
CREATE FUNCTION "stock_movement_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'StockMovement is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "StockMovement_append_only_row"
  BEFORE UPDATE OR DELETE ON "StockMovement"
  FOR EACH ROW EXECUTE FUNCTION "stock_movement_append_only"();

CREATE TRIGGER "StockMovement_append_only_truncate"
  BEFORE TRUNCATE ON "StockMovement"
  FOR EACH STATEMENT EXECUTE FUNCTION "stock_movement_append_only"();
